<script>
const statusUrl=document.body.dataset.statusUrl;let currentSlide=document.querySelector('[data-slide-id]')?.dataset.slideId||'{{ $current?->id ?? '' }}';let currentSlideVersion=Number(document.querySelector('[data-slide-version]')?.dataset.slideVersion||'{{ $current_version }}');let currentLive={{ $live ? 'true' : 'false' }};let currentChapterId=String(document.querySelector('[data-chapter-id]')?.dataset.chapterId||'');let currentChapterVersion=Number(document.querySelector('[data-chapter-version]')?.dataset.chapterVersion||0);let currentTopicId=String(document.querySelector('[data-topic-id]')?.dataset.topicId||'');let currentTopicVersion=Number(document.querySelector('[data-topic-version]')?.dataset.topicVersion||0);let currentPresentedGroup=document.body.dataset.presentedGroup||'';let currentPresentedGroupVersion=Number(document.body.dataset.presentedGroupVersion||0);const initialAssessment=document.getElementById('assessment-data');const initialAssessmentData=initialAssessment?JSON.parse(initialAssessment.textContent):null;let currentPhase=initialAssessmentData?.phase||'';let currentEnds=initialAssessmentData?.ends_at_ms??null;let currentLeaderboardVersion=Number(document.querySelector('[data-leaderboard-version]')?.dataset.leaderboardVersion||0);let currentAssessmentResultsVersion=Number(document.querySelector('[data-assessment-results-version]')?.dataset.assessmentResultsVersion||0);let currentSectionPhase='{{ $section_timer['phase'] ?? '' }}';let currentSectionEnd={{ $section_timer['ends_at_ms'] ?? 'null' }};const sectionTimer=document.getElementById('student-section-clock');
async function syncRoom(){try{const r=await fetch(statusUrl,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();const slide=String(d.current?.id||'');const version=Number(d.current_version||0);const chapterId=String(d.presented_chapter?.id||'');const chapterVersion=Number(d.presented_chapter?.version||0);const topicId=String(d.presented_topic?.id||'');const topicVersion=Number(d.presented_topic?.version||0);const phase=d.assessment?.phase||'';const ends=d.assessment?.ends_at_ms??null;const leaderboardVersion=Number(d.leaderboard_version||0);const assessmentResultsVersion=Number(d.assessment_results?.version||0);const sectionPhase=d.section_timer?.phase||'';const sectionEnd=d.section_timer?.ends_at_ms??null;const presentedGroup=String(d.presented_group?.label||'');const presentedGroupVersion=Number(d.presented_group?.version||0);if(d.live!==currentLive||slide!==currentSlide||version!==currentSlideVersion||chapterId!==currentChapterId||chapterVersion!==currentChapterVersion||topicId!==currentTopicId||topicVersion!==currentTopicVersion||presentedGroup!==currentPresentedGroup||presentedGroupVersion!==currentPresentedGroupVersion||phase!==currentPhase||leaderboardVersion!==currentLeaderboardVersion||assessmentResultsVersion!==currentAssessmentResultsVersion||sectionPhase!==currentSectionPhase)location.reload();if(ends!==currentEnds){currentEnds=ends;const timer=document.getElementById('quiz-timer');if(timer&&ends!==null)timer.dataset.end=String(ends)}if(sectionEnd!==currentSectionEnd){currentSectionEnd=sectionEnd;if(sectionTimer&&sectionEnd!==null)sectionTimer.dataset.end=String(sectionEnd)}}catch(e){}}
setInterval(syncRoom,2200);
const groupActivityRoot=document.getElementById('group-activity-live');if(groupActivityRoot){let groupActivityVersion=-1;let groupActivityTimerFinished=null;const csrfToken=document.querySelector('meta[name="csrf-token"]').content;function renderGroupActivity(data){if(data.version===groupActivityVersion&&data.timer_finished===groupActivityTimerFinished)return;groupActivityTimerFinished=data.timer_finished;const drafts=new Map([...groupActivityRoot.querySelectorAll('[data-draft-key]')].map(field=>[field.dataset.draftKey,field.value]));if([...groupActivityRoot.querySelectorAll('input[type="file"]')].some(field=>field.files.length))return;groupActivityVersion=data.version;const sections=data.sections||[];groupActivityRoot.replaceChildren();if(groupActivityRoot.dataset.instructions){const instructions=document.createElement('p');instructions.className='group-activity-instructions';instructions.textContent=groupActivityRoot.dataset.instructions;groupActivityRoot.append(instructions)}if(!sections.length){groupActivityRoot.innerHTML='<div class="eyebrow">GROUP ACTIVITY</div><p>No activity sections have been added yet.</p>';return}for(const section of sections){const card=document.createElement('article');card.className='group-activity-section';const heading=document.createElement('header');const title=document.createElement('h2');title.textContent=section.title;const type=document.createElement('span');type.className='group-activity-type';type.textContent=section.input_type+' submission';heading.append(title,type);card.append(heading);const preview=document.createElement('div');preview.className='group-activity-output';const submission=section.submission;if(submission?.text_content){const text=document.createElement('pre');text.textContent=submission.text_content;preview.append(text)}else if(submission?.file_url){if(section.input_type==='image'){const image=document.createElement('img');image.src=submission.file_url;image.alt=section.title+' group output';preview.append(image)}else{const link=document.createElement('a');link.href=submission.file_url;link.textContent=submission.file_name||'Download group output';link.target='_blank';link.rel='noopener';preview.append(link)}}else{const empty=document.createElement('p');empty.className='group-activity-empty';empty.textContent='No group output has been submitted yet.';preview.append(empty)}card.append(preview);if(submission||data.timer_finished){const notice=document.createElement('p');notice.className='group-activity-end-message';notice.textContent='Your group output will be graded manually by your Resource Speaker';card.append(notice)}if(data.is_group_leader&&data.can_edit){const outputForm=document.createElement('form');outputForm.method='post';outputForm.action=section.submission_url;outputForm.enctype='multipart/form-data';outputForm.className='group-activity-output-form';outputForm.innerHTML='<input type="hidden" name="_token" value="'+csrfToken+'">';if(section.input_type==='text'){const input=document.createElement('textarea');input.name='text_content';input.rows=5;input.maxLength=20000;input.placeholder='Write your group’s work…';input.dataset.draftKey='output-'+section.id;input.value=drafts.get(input.dataset.draftKey)||submission?.text_content||'';outputForm.append(input)}else{const input=document.createElement('input');input.type='file';input.name='submission_file';input.required=!submission?.file_url;input.accept=section.input_type==='image'?'image/jpeg,image/png,image/webp,image/gif':'.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.csv,.txt,.zip,.mp3,.wav,.mp4,.mov';outputForm.append(input)}const save=document.createElement('button');save.className='button primary';save.textContent=submission?'Save changes':'Submit group work';outputForm.append(save);if(submission){outputForm.hidden=true;const editButton=document.createElement('button');editButton.type='button';editButton.className='button ghost';editButton.textContent='Edit work';editButton.addEventListener('click',()=>{outputForm.hidden=!outputForm.hidden;editButton.textContent=outputForm.hidden?'Edit work':'Cancel editing'});card.append(editButton)}card.append(outputForm)}const comments=document.createElement('div');comments.className='group-activity-comments';for(const status of ['pending','considered','disregarded']){const matching=(section.comments||[]).filter(comment=>comment.status===status);const bucket=document.createElement('section');bucket.className='group-activity-comment-bucket status-'+status;const bucketTitle=document.createElement('h3');bucketTitle.textContent=status[0].toUpperCase()+status.slice(1)+' · '+matching.length;bucket.append(bucketTitle);if(!matching.length){const none=document.createElement('p');none.textContent='No '+status+' suggestions.';bucket.append(none)}for(const comment of matching){const row=document.createElement('article');row.className='group-activity-comment';const copy=document.createElement('p');copy.textContent=comment.body;const author=document.createElement('small');author.textContent=comment.name+' · '+comment.created_at;row.append(copy,author);if(data.is_group_leader&&status==='pending'){const actions=document.createElement('div');actions.className='group-activity-comment-actions';for(const [nextStatus,label] of [['considered','✓ Consider'],['disregarded','× Disregard']]){const review=document.createElement('form');review.method='post';review.action='/client/group-activity/comments/'+comment.id+'/review?event_id='+data.event_id;review.innerHTML='<input type="hidden" name="_token" value="'+csrfToken+'"><input type="hidden" name="event_id" value="'+data.event_id+'"><input type="hidden" name="status" value="'+nextStatus+'">';const button=document.createElement('button');button.className='button ghost';button.textContent=label;review.append(button);actions.append(review)}row.append(actions)}bucket.append(row)}comments.append(bucket)}card.append(comments);const commentForm=document.createElement('form');commentForm.method='post';commentForm.action=section.comment_url;commentForm.className='group-activity-comment-form';commentForm.innerHTML='<input type="hidden" name="_token" value="'+csrfToken+'">';const commentInput=document.createElement('textarea');commentInput.name='body';commentInput.rows=2;commentInput.maxLength=2000;commentInput.required=true;commentInput.placeholder='Suggest an idea for this section…';commentInput.dataset.draftKey='comment-'+section.id;commentInput.value=drafts.get(commentInput.dataset.draftKey)||'';const commentButton=document.createElement('button');commentButton.className='button ghost';commentButton.textContent='Add suggestion';commentForm.append(commentInput,commentButton);card.append(commentForm);groupActivityRoot.append(card)}}async function refreshGroupActivity(){try{const response=await fetch(groupActivityRoot.dataset.liveUrl,{headers:{Accept:'application/json'}});if(response.ok)renderGroupActivity(await response.json())}catch(error){}}refreshGroupActivity();setInterval(refreshGroupActivity,2500)}
const pauseCountdown=document.querySelector('.pause-countdown');if(pauseCountdown){function updatePauseCountdown(){const seconds=Math.max(0,Math.ceil((Number(pauseCountdown.dataset.end)-Date.now())/1000));pauseCountdown.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}updatePauseCountdown();setInterval(updatePauseCountdown,1000)}
if(sectionTimer&&sectionTimer.dataset.phase==='running'){function updateSectionTimer(){const seconds=Math.max(0,Math.floor((Number(sectionTimer.dataset.end)-Date.now())/1000));sectionTimer.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds===0)location.reload()}updateSectionTimer();setInterval(updateSectionTimer,1000)}

const dataNode=document.getElementById('assessment-data');if(dataNode){const assessment=JSON.parse(dataNode.textContent);if(assessment.phase==='quiz')initQuiz(assessment)}
const studentConfirmation=document.getElementById('student-confirmation');let studentConfirmationResolve=null;function confirmStudentSubmission(){studentConfirmation.showModal();return new Promise(resolve=>{studentConfirmationResolve=resolve})}studentConfirmation.querySelector('[data-student-cancel]').addEventListener('click',()=>studentConfirmation.close('cancel'));studentConfirmation.querySelector('[data-student-accept]').addEventListener('click',()=>studentConfirmation.close('accept'));studentConfirmation.addEventListener('close',()=>{if(studentConfirmationResolve){studentConfirmationResolve(studentConfirmation.returnValue==='accept');studentConfirmationResolve=null}});studentConfirmation.addEventListener('click',event=>{if(event.target===studentConfirmation)studentConfirmation.close('cancel')});
function initQuiz(assessment){
 const questions=assessment.questions||[], screen=document.getElementById('assessment-screen');if(!questions.length)return;
 const key='decks:'+screen.dataset.attendee+':'+assessment.slide_id;let index=Math.min(Number(assessment.resume_position??localStorage.getItem(key)??0),questions.length-1);let progressQueue=Promise.resolve();
 const timer=document.getElementById('quiz-timer'), progress=document.getElementById('assessment-progress'), fill=document.getElementById('progress-fill'), panel=document.getElementById('quiz-question'), jump=document.getElementById('question-jump'), prev=document.getElementById('previous-question'), next=document.getElementById('next-question'), finishButton=document.getElementById('finish-assessment'), saveState=document.getElementById('save-state');
 const csrf=document.querySelector('meta[name="csrf-token"]').content, saveQueues=new Map();
 function persistProgress(){const position=index;progressQueue=progressQueue.catch(()=>{}).then(()=>fetch('{{ route('client.assessment.progress') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({question_index:position})}));}
 function setSaved(state){saveState.classList.toggle('saving',state==='saving');saveState.classList.toggle('save-error',state==='error');saveState.innerHTML=state==='saving'?'<span class="save-spinner"></span> Saving…':state==='error'?'<span>!</span> Could not save — retry':'<span class="save-check">✓</span> All changes saved'}
 function save(q,value){q.answer=value;setSaved('saving');const previous=saveQueues.get(q.id)||Promise.resolve();const task=previous.catch(()=>{}).then(async()=>{const res=await fetch('{{ route('client.assessment.answer') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({question_id:q.id,answer:q.answer})});if(!res.ok)throw Error();setSaved('saved')}).catch(error=>{setSaved('error');throw error});saveQueues.set(q.id,task);task.catch(()=>{});return task}
 let submissionInProgress=false;
 function updateTimer(){const left=Math.max(0,Math.floor((Number(timer.dataset.end)-Date.now())/1000));timer.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');if(left===0){submitAssessment(true)}}
 function element(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
 function makeChoice(q,option,multiple){const label=element('label','quiz-option');const input=document.createElement('input');input.type=multiple?'checkbox':'radio';input.name='question-'+q.id;input.value=option;input.checked=multiple?Array.isArray(q.answer)&&q.answer.includes(option):q.answer===option;const copy=element('span','quiz-option-copy',option);label.append(input,copy);input.addEventListener('change',()=>{let value=multiple?[...panel.querySelectorAll('input:checked')].map(x=>x.value):input.value;save(q,value)});return label}
 function render(){const q=questions[index];panel.replaceChildren();const header=element('div','question-type-label',({single_choice:'CHOOSE ONE',multiple_choice:'CHOOSE ALL THAT APPLY',short_answer:'YOUR RESPONSE',true_false:'TRUE OR FALSE',ordering:'ARRANGE IN ORDER',matching:'MATCH THE PAIRS'})[q.type]||'QUESTION');panel.append(header,element('h1','question-prompt',q.prompt));
   if(q.type==='single_choice'||q.type==='true_false'){const list=element('div','quiz-options');(q.options||['True','False']).forEach(o=>list.append(makeChoice(q,o,false)));panel.append(list)}
   if(q.type==='multiple_choice'){const list=element('div','quiz-options');(q.options||[]).forEach(o=>list.append(makeChoice(q,o,true)));panel.append(list)}
   if(q.type==='short_answer'){const wrap=element('div','short-answer-wrap');const area=document.createElement('textarea');area.rows=5;area.placeholder='Type your answer here…';area.value=typeof q.answer==='string'?q.answer:'';area.setAttribute('aria-label','Your answer');wrap.append(area);panel.append(wrap);let debounce;area.addEventListener('input',()=>{clearTimeout(debounce);setSaved('saving');debounce=setTimeout(()=>save(q,area.value),350)});area.addEventListener('blur',()=>{if(area.value)save(q,area.value)})}
   if(q.type==='ordering'){const list=element('ol','ordering-list');(Array.isArray(q.answer)?q.answer:q.options||[]).forEach((item,n)=>{const row=element('li','ordering-item');row.draggable=true;row.dataset.index=n;row.append(element('span','drag-grip','⠿'),element('span','ordering-label',item));const controls=element('span','order-controls');['↑','↓'].forEach((arrow,dir)=>{const b=element('button','order-move',arrow);b.type='button';b.setAttribute('aria-label',dir===0?'Move up':'Move down');b.disabled=dir===0?n===0:n===list.children.length-1;b.addEventListener('click',()=>{const arr=[...list.querySelectorAll('.ordering-label')].map(x=>x.textContent),target=n+(dir===0?-1:1);[arr[n],arr[target]]=[arr[target],arr[n]];q.answer=arr;save(q,arr);render()});controls.append(b)});row.append(controls);row.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',n);row.classList.add('dragging')});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.addEventListener('dragover',e=>e.preventDefault());row.addEventListener('drop',e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain')),to=n;const arr=[...list.querySelectorAll('.ordering-label')].map(x=>x.textContent);arr.splice(to,0,arr.splice(from,1)[0]);q.answer=arr;save(q,arr);render()});list.append(row)});panel.append(element('p','helper-copy','Drag items or use the arrows to change their order.'))}
   if(q.type==='matching'){const entries=q.options||[], existing=q.answer&&typeof q.answer==='object'?q.answer:{};const list=element('div','matching-list');const rights=entries.map(p=>p.right);entries.forEach(pair=>{const row=element('div','matching-row');row.append(element('span','matching-left',pair.left));const select=document.createElement('select');select.setAttribute('aria-label','Match for '+pair.left);select.append(new Option('Choose a match…',''));rights.forEach(right=>select.append(new Option(right,right)));select.value=existing[pair.left]||'';select.addEventListener('change',()=>{const answer={...existing,[pair.left]:select.value};q.answer=answer;save(q,answer)});row.append(select);list.append(row)});panel.append(list)}
   progress.textContent='QUESTION '+String(index+1).padStart(2,'0')+' OF '+String(questions.length).padStart(2,'0');fill.style.width=((index+1)/questions.length*100)+'%';prev.disabled=index===0;next.disabled=index===questions.length-1;next.innerHTML=index===questions.length-1?'Last question':'Next question <span>→</span>';jump.replaceChildren();questions.forEach((item,i)=>{const b=element('button','jump-button'+(i===index?' active':'')+(item.answer!==null?' answered':''),String(i+1));b.type='button';b.setAttribute('aria-label','Go to question '+(i+1));b.addEventListener('click',()=>go(i));jump.append(b)});localStorage.setItem(key,index)}
 function go(i){index=Math.max(0,Math.min(i,questions.length-1));render();persistProgress();window.scrollTo({top:0,behavior:'smooth'})}
 async function submitAssessment(automatic=false){if(submissionInProgress)return;if(!automatic&&!await confirmStudentSubmission())return;submissionInProgress=true;finishButton.disabled=true;prev.disabled=true;next.disabled=true;finishButton.textContent=automatic?'Submitting…':'Submitting…';try{if(!automatic){const activeAnswer=panel.querySelector('textarea');if(activeAnswer)await save(questions[index],activeAnswer.value)}const pendingSaves=[...saveQueues.values()];if(automatic){await Promise.allSettled(pendingSaves)}else{await Promise.all(pendingSaves)}const response=await fetch('{{ route('client.assessment.finish') }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({slide_id:assessment.slide_id})});if(!response.ok)throw Error();location.reload()}catch(error){setSaved('error');if(automatic){setTimeout(()=>{submissionInProgress=false;submitAssessment(true)},2000);return}submissionInProgress=false;finishButton.disabled=false;finishButton.textContent='Finish assessment';prev.disabled=index===0;next.disabled=index===questions.length-1}}
 prev.addEventListener('click',()=>go(index-1));next.addEventListener('click',()=>go(index+1));finishButton.addEventListener('click',submitAssessment);render();updateTimer();setInterval(updateTimer,1000)
}
</script><script src="{{ asset('theme.js').'?v=20261103-event-view-toggle' }}"></script><script src="{{ asset('video-volume.js').'?v=20261027-volume-80' }}"></script></body></html>
